let colors = ['#7B62A3', '#213668', '#F27DC0', '#4176DD', '#f0f0f0'];
let ctx;
let centerX, centerY;
let cells = [];
let rects = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	let cellCount = 20;
	let gridArea = width;
	let cellSize = gridArea / cellCount;
	background('#e3e3e3');
	for (let j = 0; j < cellCount; j++) {
		for (let i = 0; i < cellCount; i++) {
			let x = i * cellSize + (cellSize / 2) + (width - gridArea) / 2;
			let y = j * cellSize + (cellSize / 2) + (height - gridArea) / 2;
			cells.push({ x: x, y: y, w: cellSize, a:0});
			if ((0 < j) && (j < cellCount) && (0 < i) && (i < (cellCount))) {
				if (random() < 0.1) {
					let a = 0;
					let w = cellSize * 2;
					if (random() < 0.5) {
						a = (TAU / 8);
						w = cellSize * sqrt(2);
					}

					let newRect = { x: x - cellSize / 2, y: y - cellSize / 2, w: w, a: a };

					let isColliding = false;
					for (let existingRect of rects) {
						if (newRect.x < existingRect.x + existingRect.w &&
							newRect.x + newRect.w > existingRect.x &&
							newRect.y < existingRect.y + existingRect.w &&
							newRect.y + newRect.w > existingRect.y) {
							isColliding = true;
							break;
						}
					}

					if (!isColliding) {
						rects.push(newRect);
					}
				}
			}
		}
	}

	background(10, 10, 15);
	for (let c of cells) {



		drawRectPattern(c.x, c.y, c.w, c.a);

	}
	for (let r of rects) {

		drawRectPattern(r.x, r.y, r.w, r.a);

	}
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;


