function drawRectPattern(x, y, w, a) {
	let type = int(random(4));

	let clr1 = clr2 = '🐇';
	while (clr1 == clr2) {
		clr1 = random(colors);
		clr2 = random(colors);
	}
	push();
	translate(x, y);
	rotate(a);
	if (type == 0) {
		concentricSquare(0, 0, w, clr1, clr2);
	}
	else if (type == 1) {
		checkeredPattern(0, 0, w, clr1, clr2);
	}
	else if (type == 2) {
		polkaDots(0, 0, w, clr1, clr2);
	}
	else if (type == 3) {
		stripePattern(0, 0, w, clr1, clr2);
	}
	pop();
}

function splitSquare(x, y, w, n) {
	n--;
	if (random() < 0.5) n -= int(random(3))
	if (n > 0) {
		splitSquare(x + (w / 4), y + (w / 4), w / 2, n);
		splitSquare(x - (w / 4), y + (w / 4), w / 2, n);
		splitSquare(x + (w / 4), y - (w / 4), w / 2, n);
		splitSquare(x - (w / 4), y - (w / 4), w / 2, n);
	} else {
		let clr1 = clr2 = '🐇';
		while (clr1 == clr2) {
			clr1 = random(colors);
			clr2 = random(colors);
		}
		let option = int(random(4))
		push();
		if (option == 0) concentricSquare(x, y, w, clr1, clr2);
		else if (option == 1) checkeredPattern(x, y, w, clr1, clr2);
		else if (option == 2) polkaDots(x, y, w, clr1, clr2);
		else if (option == 3) stripePattern(x, y, w, clr1, clr2);
		pop();
	}
}


function concentricSquare(x, y, w, clr1, clr2) {
	let num = int(random(3, 12));
	noStroke();
	for (let i = 0; i < num; i++) {
		let ww = map(i, 0, num - 1, w, 0);
		if (i % 2 == 0) fill(clr1);
		else fill(clr2);
		rect(x, y, ww, ww);
		ctx.clip();
	}
}

function checkeredPattern(x, y, w, clr1, clr2) {
	let num = int(random(2, 6));
	let cellSize = w / num;
	push();
	translate(x, y);
	noStroke();
	fill(clr1);
	rect(0, 0, w, w);
	translate(- (w / 2), - (w / 2));
	ctx.clip();
	for (let j = 0; j < num; j++) {
		for (let i = 0; i < num; i++) {
			let cellX = i * cellSize + (cellSize / 2);
			let cellY = j * cellSize + (cellSize / 2);
			if ((i + j) % 2 == 0) {
				fill(clr2);
				rect(cellX, cellY, cellSize, cellSize);
			}
			fill(random(colors));
			rect(cellX, cellY, cellSize * 0.25, cellSize * 0.25);
		}
	}
	pop();
}

function polkaDots(x, y, w, clr1, clr2) {
	let num = int(random(2, 8));
	let cellSize = w / num;
	push();
	translate(x, y);
	noStroke();
	fill(clr1);
	rect(0, 0, w, w);
	translate(- (w / 2), - (w / 2));
	ctx.clip();
	for (let j = 0; j < num; j++) {
		for (let i = 0; i < num; i++) {
			let cellX = i * cellSize + (cellSize / 2);
			let cellY = j * cellSize + (cellSize / 2);
			fill(clr2);
			circle(cellX, cellY, cellSize * 0.75);
			fill(random(colors))
			circle(cellX, cellY, cellSize * 0.5);
		}
	}
	pop();
}

function stripePattern(x, y, w, clr1, clr2) {
	let num = int(random(5, 8));
	let cellSize = w / num;
	push();
	translate(x, y);
	rotate(int(random(2)) * PI / 2);
	noStroke();
	fill(clr1);
	rect(0, 0, w, w);
	translate(- (w / 2), - (w / 2));
	ctx.clip();
	for (let j = 0; j < num; j++) {
		for (let i = 0; i < num; i++) {
			let cellX = i * cellSize + (cellSize / 2);
			let cellY = j * cellSize + (cellSize / 2);
			fill(clr2);
			rect(cellX, cellY, cellSize * 0.5, cellSize * 1.01);
		}
	}
	pop();
}

